class Solution {
    private long total,maximum;
    public int maxProduct(TreeNode root){
        total=sum(root);
        sumAndProduct(root);
        return (int)(maximum%1000000007L);
    }
    private long sum(TreeNode node){
        return node==null?0:node.val+sum(node.left)+sum(node.right);
    }
    private long sumAndProduct(TreeNode node){
        if(node==null)return 0;
        long sub=node.val+sumAndProduct(node.left)+sumAndProduct(node.right);
        maximum=Math.max(maximum,sub*(total-sub));
        return sub;
    }
}

code.kotlin:
class Solution {
    private var total=0L;
    private var maximum=0L;
    fun maxProduct(root:TreeNode?):Int{
        total=sum(root);
        sumAndProduct(root);
        return (maximum%1000000007L).toInt()
    };
    private fun sum(node:TreeNode?):Long=node?.let{
        it.`val`+sum(it.left)+sum(it.right)
    }?:0L;
    private fun sumAndProduct(node:TreeNode?):Long{
        node?:return 0;
        val sub=node.`val`+sumAndProduct(node.left)+sumAndProduct(node.right);
        maximum=maxOf(maximum,sub*(total-sub));
        return sub
    }
}

